package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.*;
import net.neoforged.neoforge.event.level.BlockEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Native placement + accepted walking authority. No client objective counts or automatic world writes. */
public final class MineAccessService {
 public static final String QUEST="kingdom_smp:miner/a04";
 private static final ProfessionQuestCatalog CATALOG=ProfessionQuestCatalog.approved(List.of(ApprovedProfessionContent.get(QUEST).slot()));
 private record Trip(MineAccessEvidence.Walk walk,Vec3 last,int tick){}
 private static final Map<ServerPlayer,Trip> TRIPS=new WeakHashMap<>();
 private static final Map<MinecraftServer,ArrayDeque<Runnable>> PENDING=new WeakHashMap<>();
 private MineAccessService(){}
 public static ProfessionQuestCatalog catalog(){return CATALOG;}
 public static boolean eligible(ServerPlayer p){var store=CommerceService.initializedStore(p.server).orElse(null);if(store==null||store.quarantined()||!TreeQuestService.real(p)||p.serverLevel().dimension()!=Level.OVERWORLD)return false;var r=store.professions(p.getUUID());return r.isActive(Profession.MINER)&&r.progressBand(Profession.MINER)==ProfessionRank.APPRENTICE&&com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier()>=3&&com.mohymods.kingdomsmp.building.ConstructionService.store(p.server).projects().stream().anyMatch(q->q.phase()==com.mohymods.kingdomsmp.persistence.ConstructionStore.Phase.COMPLETE&&!q.npcDead()&&q.blueprint().toString().equals(Profession.MINER.buildingId()));}
 public static void register(IEventBus bus){bus.addListener(EventPriority.LOWEST,false,BlockEvent.EntityPlaceEvent.class,MineAccessService::place);bus.addListener(MineAccessService::tick);bus.addListener((net.neoforged.neoforge.event.server.ServerStoppedEvent e)->{PENDING.remove(e.getServer());TRIPS.keySet().removeIf(p->p.server==e.getServer());});}
 private static void place(BlockEvent.EntityPlaceEvent event){if(!(event.getEntity() instanceof ServerPlayer p)||!(event.getLevel() instanceof ServerLevel level)||!level.getServer().isSameThread())return;try{if(!eligible(p))return;var pos=event.getPos().immutable();var state=event.getPlacedBlock();String block=BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();if(!MineAccessEvidence.material(block)||event.getBlockSnapshot().getState().getBlock()==state.getBlock())return;var queue=PENDING.computeIfAbsent(p.server,s->new ArrayDeque<>());if(queue.size()>=4096)return;queue.add(()->{if(event.isCanceled()||!eligible(p)||p.serverLevel()!=level||!level.hasChunkAt(pos)||!level.getBlockState(pos).equals(state)||!state.canSurvive(level,pos)||!level.getWorldBorder().isWithinBounds(pos)||PlacementProtection.check(level,p,pos,pos)!=null)return;LayeredInteriorInspection.requirePlayerProject(p,pos,pos);var data=MineAccessSavedData.get(p.server);if(data.evidence().record(new MineAccessEvidence.Cell(level.dimension().location().toString(),pos.asLong()),new MineAccessEvidence.Mark(p.getUUID(),block)))data.setDirty();});}catch(RuntimeException e){TreeLifecycle.failure(p.server,e);}}
 private static void tick(ServerTickEvent.Post event){var tasks=PENDING.remove(event.getServer());if(tasks!=null)while(!tasks.isEmpty())try{tasks.removeFirst().run();}catch(RuntimeException e){TreeLifecycle.failure(event.getServer(),e);}}
 public static void changed(LevelChunk chunk,BlockPos pos,BlockState before,BlockState after){try{if(before==null||before.getBlock()==after.getBlock()||!(chunk.getLevel() instanceof ServerLevel level)||!level.getServer().isSameThread()||!MineAccessEvidence.material(BuiltInRegistries.BLOCK.getKey(before.getBlock()).toString())||!MineAccessSavedData.present(level.getServer()))return;var data=MineAccessSavedData.get(level.getServer());if(data.evidence().remove(new MineAccessEvidence.Cell(level.dimension().location().toString(),pos.asLong())))data.setDirty();}catch(RuntimeException e){if(chunk.getLevel() instanceof ServerLevel level)TreeLifecycle.failure(level.getServer(),e);}}
 public static void interrupt(net.minecraft.world.entity.Entity entity){if(entity instanceof ServerPlayer p)TRIPS.remove(p);}
 public record Frame(ServerPlayer player,ServerLevel level,Vec3 before){}
 public static Frame capture(ServerPlayer p,Vec3 awaiting){try{if(!p.server.isSameThread())return null;if(awaiting!=null||!eligible(p)||p.isPassenger()||p.getAbilities().flying){interrupt(p);return null;}return new Frame(p,p.serverLevel(),p.position());}catch(RuntimeException e){TreeLifecycle.failure(p.server,e);return null;}}
 /** Read actual collision shapes rather than a client onGround bit. Initially validated stair/slab/floor routes. */
 public static BlockPos support(ServerPlayer p){var level=p.serverLevel();var pos=BlockPos.containing(p.getX(),p.getBoundingBox().minY-.02,p.getZ());if(!level.hasChunkAt(pos)||p.isInWaterOrBubble()||p.isInLava()||!level.noCollision(p,p.getBoundingBox().deflate(.00001)))return null;var state=level.getBlockState(pos);if(!state.getFluidState().isEmpty()||!state.canSurvive(level,pos))return null;double x=p.getX()-pos.getX(),z=p.getZ()-pos.getZ(),y=p.getBoundingBox().minY-pos.getY();return state.getCollisionShape(level,pos).toAabbs().stream().anyMatch(b->x>=b.minX&&x<=b.maxX&&z>=b.minZ&&z<=b.maxZ&&Math.abs(y-b.maxY)<.08)?pos:null;}
 public static void moved(Frame frame,Vec3 awaiting){if(frame==null)return;var p=frame.player();try{if(awaiting!=null||p.serverLevel()!=frame.level()||!eligible(p)){interrupt(p);return;}double distance=p.position().distanceToSqr(frame.before());if(distance<.0001)return;if(distance>4){interrupt(p);return;}var old=TRIPS.get(p);if(old!=null&&(old.last().distanceToSqr(frame.before())>.25||p.server.getTickCount()-old.tick()>40)){interrupt(p);old=null;}var pos=support(p);if(pos==null){if(old!=null)TRIPS.put(p,new Trip(old.walk(),p.position(),p.server.getTickCount()));return;}var level=p.serverLevel();var data=MineAccessSavedData.get(p.server);var mark=data.evidence().mark(new MineAccessEvidence.Cell(level.dimension().location().toString(),pos.asLong())).orElse(null);if(mark==null||!mark.player().equals(p.getUUID())||!mark.block().equals(BuiltInRegistries.BLOCK.getKey(level.getBlockState(pos).getBlock()).toString())||PlacementProtection.check(level,p,pos,pos.above(2))!=null){interrupt(p);return;}LayeredInteriorInspection.requirePlayerProject(p,pos,pos.above(2));if(old==null){if(pos.getY()<0)return;old=new Trip(new MineAccessEvidence.Walk(pos.asLong()),p.position(),p.server.getTickCount());}else if(!old.walk().step(pos.asLong())){interrupt(p);return;}TRIPS.put(p,new Trip(old.walk(),p.position(),p.server.getTickCount()));int goal=MineAccessRules.get(p.server).routeCells();if(old.walk().returned(goal)){if(data.evidence().complete(p.getUUID(),level.dimension().location().toString(),old.walk(),goal)){data.setDirty();p.sendSystemMessage(Component.literal("Safe mine descent and return recorded. Maintain the access and visit Doran to review your earned objective."));}interrupt(p);}}catch(RuntimeException e){interrupt(p);TreeLifecycle.failure(p.server,e);}}
 public static String validate(ServerPlayer p){var route=MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow(()->new IllegalStateException("Walk your retained placed stair/floor route from Y0 or above to below Y0 and back onto its starting block. Teleports/restarts interrupt an unfinished trip; retained placements remain."));if(!route.dimension().equals(p.serverLevel().dimension().location().toString())||route.cells().size()<MineAccessRules.get(p.server).routeCells())throw new IllegalStateException("Maintain the configured route in its original Overworld");var facts=new StringBuilder(route.id().toString());for(long cell:route.cells()){var pos=BlockPos.of(cell);var level=p.serverLevel();if(!level.hasChunkAt(pos)||!level.getWorldBorder().isWithinBounds(pos))throw new IllegalStateException("Visit the full route first; no chunks are loaded for progression");var mark=MineAccessSavedData.get(p.server).evidence().mark(new MineAccessEvidence.Cell(route.dimension(),cell)).orElseThrow(()->new IllegalStateException("Retain the actual player-built access blocks or walk a newly built route"));var state=level.getBlockState(pos);if(!mark.player().equals(p.getUUID())||!mark.block().equals(BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString())||!state.getFluidState().isEmpty()||!state.canSurvive(level,pos)||!level.getBlockState(pos.above()).getCollisionShape(level,pos.above()).isEmpty()||!level.getBlockState(pos.above(2)).getCollisionShape(level,pos.above(2)).isEmpty()||PlacementProtection.check(level,p,pos,pos.above(2))!=null)throw new IllegalStateException("Route materials, support or permission changed");LayeredInteriorInspection.requirePlayerProject(p,pos,pos.above(2));facts.append('|').append(cell).append('=').append(state);}try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(facts.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),0,16);}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public static boolean ready(ServerPlayer p){try{return eligible(p)&&!CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).completedQuestIds().contains(QUEST)&&!validate(p).isEmpty();}catch(IllegalStateException unavailable){return false;}}
 public static String status(ServerPlayer p){try{if(MineAccessSavedData.present(p.server))MineAccessSavedData.get(p.server);}catch(IllegalStateException unavailable){return "Mine evidence unavailable. An operator must restore its matching checkpoint; existing earned records and normal item/movement operations remain preserved.";}var trip=TRIPS.get(p);return "Build and retain a permitted walking stair/slab/floor access while Miner is active. Walk at least "+MineAccessRules.get(p.server).routeCells()+" distinct supplied supports from above Y0 to below Y0 and back onto the same starting support. Unknown old/kingdom blocks, flying and teleports grant no credit. "+(trip==null?"Start on your placed access above Y0.":"Current walk "+trip.walk().cells().size()+" supports; entry "+BlockPos.of(trip.walk().entry()).toShortString());}
 public static void complete(ServerPlayer p,UUID operation)throws java.io.IOException{ContractService.requireCounter(p,Profession.MINER);if(!ready(p))throw new IllegalStateException(status(p));CommerceService.store(p.server).completeMineAccess(operation,p.getUUID(),validate(p),MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow().cells().size());}
}
